package billing

import (
	"context"
	"time"

	"github.com/ClickHouse/clickhouse-go/v2"
)

type StatusUpdate struct {
	TenantID  uint32
	CreatedAt time.Time
	EventID   string
	Status    string
	UpdatedAt time.Time
	IsDeleted uint8
}

func ApplyStatusUpdates(ctx context.Context, conn clickhouse.Conn, updates []StatusUpdate) error {
	for _, u := range updates {
		err := conn.Exec(
			ctx,
			`ALTER TABLE billing_events UPDATE status = {status:String}, updated_at = {updated_at:DateTime64(3, 'UTC')}, is_deleted = {is_deleted:UInt8} WHERE tenant_id = {tenant_id:UInt32} AND event_id = {event_id:UUID}`,
			clickhouse.Named("status", u.Status),
			clickhouse.Named("updated_at", u.UpdatedAt),
			clickhouse.Named("is_deleted", u.IsDeleted),
			clickhouse.Named("tenant_id", u.TenantID),
			clickhouse.Named("event_id", u.EventID),
		)
		if err != nil {
			return err
		}
	}
	return nil
}

package billing

import (
	"context"
	"time"

	"github.com/ClickHouse/clickhouse-go/v2"
)

type StatusUpdate struct {
	TenantID  uint32
	CreatedAt time.Time
	EventID   string
	Status    string
	UpdatedAt time.Time
	IsDeleted uint8
}

func ApplyStatusUpdates(ctx context.Context, conn clickhouse.Conn, updates []StatusUpdate) error {
	if len(updates) == 0 {
		return nil
	}
	batch, err := conn.PrepareBatch(ctx, `INSERT INTO billing_events (tenant_id, created_at, event_id, status, updated_at, is_deleted)`)
	if err != nil {
		return err
	}
	defer func() { _ = batch.Close() }()
	for _, u := range updates {
		if err := batch.Append(u.TenantID, u.CreatedAt, u.EventID, u.Status, u.UpdatedAt, u.IsDeleted); err != nil {
			_ = batch.Abort()
			return err
		}
	}
	return batch.Send()
}

